BEGIN;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM project_issues) OR EXISTS (SELECT 1 FROM development_tasks) OR EXISTS (SELECT 1 FROM project_deliverables) OR EXISTS (SELECT 1 FROM system_workflows WHERE revision <> 1) THEN
    RAISE EXCEPTION 'Workflow handoffs require fresh business data; use a new database/schema. Existing data is not converted or deleted.';
  END IF;
END $$;
ALTER TABLE work_actions ADD COLUMN explicit_handler BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE project_deliverables ADD COLUMN action_id TEXT, ADD COLUMN request_id TEXT;
CREATE UNIQUE INDEX project_deliverables_request_id_key ON project_deliverables(request_id);
CREATE TABLE workflow_execution_events (
  id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES development_tasks(id) ON DELETE RESTRICT ON UPDATE CASCADE,
  turn_id TEXT NOT NULL, steps JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'pending', error TEXT,
  created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT workflow_execution_events_status_check CHECK (status IN ('pending','applied','blocked'))
);
CREATE UNIQUE INDEX workflow_execution_events_task_id_turn_id_key ON workflow_execution_events(task_id,turn_id);
